{
  "probability": 0.47,
  "range_low": 0.38,
  "range_high": 0.56,
  "summary": [
    "The analysis yields a non-trivial chance of a 2/3 majority arising in 2026 Hungary, though no clear consensus supports a sure path to 133+ seats.",
    "Electoral-system disproportionality amplifies lead blocs, so near-majority vote shares could translate into a 2/3 seat share under favorable turnout conditions.",
    "Opposition unity behind a single front (TISZA) could lift the probability if mobilization favors that bloc and vote consolidation holds.",
    "Polls are divergent and momentum is uncertain, making the probability sensitive to turnout dynamics and coalition timing."
  ],
  "confidence": "medium",
  "narrative": "Starting from a conservative baseline and incorporating factors such as the system's amplification of lead blocs, potential opposition unity, and ongoing poll volatility, the calibrated estimate places the chance of any party or coalition reaching a 2/3 majority around 0.47 with a modest uncertainty band.",
  "justification": {
    "anchor": {
      "probability": 0.32,
      "basis": "Baseline probability from forecasts focusing on a 2/3 threshold under Hungary’s current electoral framework, reflecting historical baselines and the observed dispersion in late-2025 to early-2026 polls."
    },
    "factor_updates": [
      {
        "factor": "Electoral-system disproportionality bias toward the largest party (winner-compensation)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Winner-compensation amplifies seat shares; if a bloc secures roughly 44–54% of votes, it can translate into about 67–68% of seats, nudging the probability toward a 2/3 outcome."
      },
      {
        "factor": "Opposition unity behind a single front (TISZA)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "A unified opposition reduces vote-splitting, increasing the chance that the bloc reaches the 133+ seat threshold if turnout favors that coalition."
      },
      {
        "factor": "Poll volatility and lack of consensus among major pollsters (Feb 2026)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Divergent polls create uncertainty about a deterministic path to a 2/3 majority, tempering the probability estimate."
      },
      {
        "factor": "Turnout dynamics and mobilization effects",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "High turnout among leading blocs can translate into stronger seat shares under the disproportional system, increasing odds of a 2/3 result."
      },
      {
        "factor": "Historical precedent of 2/3 majorities under favorable conditions",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Past elections show the possibility of a 2/3 majority when conditions align; current conditions are mixed but not devoid of such potential."
      }
    ],
    "synthesis_rationale": "Beginning with a cautious anchor around 0.32 (low base-rate) and applying both upward and downward updates from structural bias, potential unity, and poll dynamics, the net effect yields a calibrated posterior near 0.47. Correlations among factors are acknowledged, and calibration accounts for residual uncertainty in turnout and coalition dynamics."
  }
}

